// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(actor != msg.sender);

        // grant the actor the TIMELock admin role (deployer holds it and it administers itself)
        bytes32 role = c.TIMELOCK_ADMIN_ROLE();
        c.grantRole(role, actor);

        vm.prank(actor);
        c.renounceRole(role, actor);

        // General rule: after renounceRole(role, self) succeeds, the account no longer holds the role.
        assertTrue(!c.hasRole(role, actor), "role must be revoked after renounce");
    }
}
